"""Render the offline economy-check JSON into the reviewable current inventory."""
import json
from pathlib import Path
import sys

ROOT = Path(__file__).resolve().parents[2]
report = json.loads(Path(sys.argv[1]).read_text(encoding="utf-8-sig"))
models = report["models"]
counts = {state: sum(m["state"] == state for m in models) for state in ["priced", "sponsored", "unavailable"]}
if counts["priced"] + counts["sponsored"] + counts["unavailable"] != len(models):
    raise ValueError("unknown economic state")
target = ROOT / "docs/research/epifera-economy-current.json"
target.write_text(json.dumps(report, ensure_ascii=False, indent=2) + "\n", encoding="utf-8")
labels = {"study24": "Study24", "cost_plus": "Себестоимость ×3", "protected_reference": "Защита себестоимости", "operator_fixed": "Утверждённая ставка", "sponsored": "Бесплатный чат"}
lines = [
    "# Экономика Epifera: полный текущий реестр", "",
    f"Версия политики: **{report['version']}**. Состояние: локальная реализация, 28 октября 2026. Публикация и реальные оплаты не выполнялись.", "",
    f"Проверено **{len(models)}** существующих моделей и маршрутов: **{counts['priced']}** с платными ставками, **{counts['sponsored']}** бесплатный чат, **{counts['unavailable']}** недоступных к оплате маршрута. Автоматически проверено **{report['quotes_checked']}** расчётов.", "",
    "## Принятые правила", "",
    "- Подходящие подтверждённые ставки Study24 используются с точными условиями размера, длительности и операции.",
    "- Для остальных наших моделей действует явная формула: зафиксированная себестоимость ×3, округление вверх до пяти звёзд. Точные закрытые коэффициенты Study24 не выдаются за известные.",
    "- Текстовые модели имеют фиксированную цену ограниченного ответа с серверными пределами ввода/вывода; это не списание по фактически использованным токенам.",
    "- Цена-ориентир проверяется против себестоимости по самому дешёвому продаваемому тарифу. При недостаточном доходе включается та же формула себестоимости ×3.",
    "- Сохраняются явно утверждённые операторские ставки: Whisper —25 за начатую минуту; бесплатный чат —0. Доходные пользовательские цены runtime DB помечаются операторскими, не теряются при загрузке.",
    "- Новые активные пополнения не могут продавать звёзды дешевле минимального уровня, использованного защитой. Тестовый магазин сохраняет существующее явное исключение.",
    "- У Suno каждый платный запрос с треком требует минимум один готовый аудиотрек. Все дополнительные варианты сохраняются бесплатно.",
    "- Пакетная цена GPT приходит с сервера: общий ввод учитывается один раз. Оба редактора используют одну функцию выбора цены пакета.",
    "- Старые задания, подтверждённые платежи и резервы сохраняют исходные суммы. Новые расхождения суммы задания с ценой видеомаршрута отвергаются до резервирования.",
    "- Цена не включает провайдерский допуск: непроверенные модели не включались, существующие ограничения входов/выходов и лимиты расходов сохранены.", "",
    "## Что дополнительно завершено", "",
    "Общая политика всех моделей и источник каждой ставки; защита от переполнения целых чисел; проверка цены против дохода тарифов; контроль новых пополнений; согласование видеомаршрутов с runtime-каталогом; серверные цены пакетов GPT и оба клиента; проверка всего реестра в обязательной команде модели/CI. Вёрстка тарифов сохранена.", "",
    "## Недоступные маршруты", "",
    "GPT-4o Mini TTS не имеет подключённого проверенного контракта исполнения и тарификации. У Hailuo2.3 Fast/Standard не подтверждена длительность, к которой относится закупочная ставка. Эти три маршрута к оплате не предлагаются. Наличие карточки будущей модели не разрешает платный запуск.", "",
    "Отдельные приложения-фотосессии, презентации и маркетплейсы имеют подготовленные калькуляторы, но их сценарии исполнения пока не подключены. Они не входят в работающий модельный каталог. Выпуск платёжного контура требует отдельного развёртывания и предусмотренной миграции финансовых таблиц.", "",
    "## Ограничения расчёта затрат", "",
    "Используются уже зафиксированные provider floors и номинальная конвертация каталога; реальный расход провайдера, валютный курс и комиссия магазина этой офлайн-проверкой не подтверждены. Защита сравнивает номинальную себестоимость с доходом до комиссии, не обещает прибыль после всех расходов.", "",
    "Ниже минимум/максимум относятся к проверенным настройкам и операциям, включая пакеты изображений. Это не отдельные квоты подписки. Изменение доступности провайдера не следует из готовности цены.", "",
    "| Модель / маршрут | Состояние цены | Мин., ⭐ | Макс., ⭐ | Правила | Проверок |",
    "| --- | --- | ---: | ---: | --- | ---: |",
]
for m in models:
    state = {"priced": "Настроена", "sponsored": "Бесплатно", "unavailable": "Недоступен"}[m["state"]]
    minimum, maximum = (str(m["min_stars"]), str(m["max_stars"])) if m["state"] != "unavailable" else ("—", "—")
    bases = ", ".join(labels[b] for b in m["bases"] or []) or "—"
    lines.append(f"| `{m['id']}` | {state} | {minimum} | {maximum} | {bases} | {m['quotes']} |")
lines += ["", "## Повторная проверка", "", "`go run ./scripts/models/check` проверяет допуск и экономику всего каталога. `go run ./scripts/economy/check` выдаёт подробный JSON. Для обновления этого реестра сохранить JSON и выполнить `python scripts/economy/render-report.py <путь-к-JSON>`. Preview чисел пересобирается через `go run ./scripts/models/preview`.", "", "Политика: [catalog-policy.json](../../internal/service/economycatalog/catalog-policy.json). Проверенные исходные ставки: [retail-policy.json](../../internal/service/economycatalog/retail-policy.json). [Runbook](../runbooks/MODEL_ECONOMY.md).", ""]
(ROOT / "docs/research/epifera-economy-2026-10-28.md").write_text("\n".join(lines), encoding="utf-8")
